protected static Iterator<String> findResourcePaths(String path,String pattern){
  if (path == null || pattern == null) {
    throw new IllegalArgumentException("Path and pattern must not be null");
  }

  try {
    Iterator<String> bufferedResult=ressourcesFiles.get(path + "/" + pattern);
    if (bufferedResult != null) {
      return bufferedResult;
    }

    ArrayList<String> propertiesList=new ArrayList<String>();
    @SuppressWarnings("unchecked") Enumeration<URL> propertiesUrls=bundleContext.getBundle().findEntries(path,pattern,false);
    if (propertiesUrls != null) {
      while (propertiesUrls.hasMoreElements()) {
        URL propertyUrl=propertiesUrls.nextElement();
        String pathPart=propertyUrl.getPath();
        if (pathPart == null || pathPart.length() <= 1) {
          continue;
        }
        String propertyFilePath=pathPart.substring(1).replaceAll("/", ".");
        propertiesList.add(propertyFilePath);
      }
    }

    Iterator<String> result=propertiesList.iterator();
    ressourcesFiles.put(path + pattern,result);
    return result;
  } catch (NullPointerException e) {
    throw new IllegalStateException("Failed to process resources", e);
  } catch (IndexOutOfBoundsException e) {
    throw new IllegalStateException("Invalid file path format", e);
  }
}
